WITH c AS (SELECT claim_id, SUM(CASE WHEN txn_type='RESERVE' THEN amount ELSE 0 END) res, SUM(CASE WHEN txn_type='PAYMENT' AND cost_type='INDEMNITY' THEN amount ELSE 0 END) paid, SUM(CASE WHEN txn_type='RECOVERY' THEN amount ELSE 0 END) rec FROM claim_txn GROUP BY 1)
SELECT (cl.closed_date IS NOT NULL) closed, count(*) n, round(avg(res),0) avg_res, round(sum(res),0) sum_res, round(sum(paid),0) paid, round(sum(rec),0) rec, sum(CASE WHEN res<0 THEN 1 ELSE 0 END) neg_res, sum(CASE WHEN abs(res)<0.005 THEN 1 ELSE 0 END) zero_res FROM c JOIN claim cl USING(claim_id) GROUP BY 1;
SELECT * FROM claim_txn WHERE claim_id IN (SELECT claim_id FROM claim_txn WHERE txn_type='RECOVERY' LIMIT 1) ORDER BY txn_date;
SELECT cl.claim_id, cl.accident_date, cl.closed_date, t.txn_date, t.txn_type, t.cost_type, t.amount FROM claim cl JOIN claim_txn t USING(claim_id) WHERE cl.claim_id IN (SELECT claim_id FROM claim WHERE closed_date IS NOT NULL LIMIT 2) ORDER BY 1,4;
